// Verification-conformance rule set for Shipshape.
// Plain text-pattern rules checked through Node runtime.
// Two required plank rules: plank-form and plank-coverage.
// These compensate for the absence of a docblock reader-backed checker.

const RULES = {
  // Rule: A @planks token must appear in a docblock immediately preceding a declaration.
  // Catches line-comment planks and in-body planks.
  "plank-form": {
    description: "@planks token must be in a docblock on a declaration, not a line comment or inline",
    check: (content, filePath) => {
      const violations = [];
      const lines = content.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        // Skip docblock lines
        if (line.trimStart().startsWith('*') || line.trimStart().startsWith('/**')) continue;
        if (line.includes('@planks(') || line.includes('@planks-provisional(')) {
          // Check if this line is inside a docblock
          const beforeThis = lines.slice(0, i + 1).join('\n');
          const lastOpen = beforeThis.lastIndexOf('/**');
          const lastClose = beforeThis.lastIndexOf('*/');
          if (lastOpen === -1 || lastClose > lastOpen) {
            violations.push({ line: i + 1, text: line.trim(), file: filePath });
          }
        }
      }
      return violations;
    }
  },

  // Rule: A @planks pattern must match a current step-definition pattern.
  // Note: full cross-reference requires reading all support files; see plank-join.mjs.
  // This rule catches planks that are textually stale (e.g. leading Given/When/Then).
  "plank-pattern-form": {
    description: "@planks string must not carry a leading Given, When, Then, And, or But keyword",
    check: (content, filePath) => {
      const violations = [];
      const lineRe = /@planks\(\s*"(Given|When|Then|And|But)\s+(.+?)"\s*\)/g;
      let match;
      while ((match = lineRe.exec(content)) !== null) {
        const lineNum = content.substring(0, match.index).split('\n').length;
        violations.push({ line: lineNum, text: match[0], file: filePath, detail: `Carries leading "${match[1]}" keyword` });
      }
      // Check @planks-provisional too
      const provRe = /@planks-provisional\(\s*"(.+?)"\s*\)/g;
      while ((match = provRe.exec(content)) !== null) {
        const ref = match[1];
        // Must be in repo-root-relative form: spec.feature:Scenario Name
        if (!ref.includes('.feature:')) {
          const lineNum = content.substring(0, match.index).split('\n').length;
          violations.push({ line: lineNum, text: match[0], file: filePath, detail: 'Not in repo-root-relative form' });
        }
      }
      return violations;
    }
  },

  // Rule: No bare # comments in .feature files
  "no-bare-comments": {
    description: "No bare # comments in feature files; use Rule: prose instead",
    check: (content, filePath) => {
      if (!filePath.endsWith('.feature')) return [];
      const violations = [];
      const lines = content.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const trimmed = lines[i].trim();
        // Skip shebang, empty lines, and lines that are part of docstrings
        if (trimmed.startsWith('#') && !trimmed.startsWith('#!') && !trimmed.startsWith('# language:')) {
          violations.push({ line: i + 1, text: trimmed, file: filePath });
        }
      }
      return violations;
    }
  },

  // Rule: No guessed literal delays where a signal is observable
  "no-guessed-delays": {
    description: "No guessed literal delays (setTimeout with literal ms > 0); prefer signals",
    check: (content, filePath) => {
      if (!filePath.endsWith('.js') && !filePath.endsWith('.mjs')) return [];
      const violations = [];
      const delayRe = /setTimeout\s*\(\s*(?:function|\(|[a-zA-Z_$][a-zA-Z0-9_$]*\s*=>)/;
      // More precise: catch setTimeout with a numeric literal
      const literalRe = /setTimeout\s*\(\s*(?:[^,]+)\s*,\s*(\d+)\s*\)/g;
      let match;
      while ((match = literalRe.exec(content)) !== null) {
        const ms = parseInt(match[1], 10);
        if (ms > 0) {
          const lineNum = content.substring(0, match.index).split('\n').length;
          violations.push({ line: lineNum, text: match[0].substring(0, 60), file: filePath, detail: `Literal delay ${ms}ms` });
        }
      }
      return violations;
    }
  }
};

async function main() {
  const root = process.cwd();
  const { readFile, readdir } = await import('node:fs/promises');
  const path = await import('node:path');
  const filesToCheck = [];

  // Collect files from implementation dirs and specs
  const dirs = ['.', 'js', 'css', 'features', 'features/support'];
  for (const dir of dirs) {
    try {
      const entries = await readdir(path.join(root, dir), { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isFile() && !entry.name.startsWith('.')) {
          filesToCheck.push(path.join(dir, entry.name));
        }
      }
    } catch {
      // directory may not exist
    }
  }

  let exitCode = 0;

  for (const relPath of filesToCheck) {
    let content;
    try {
      content = await readFile(path.join(root, relPath), 'utf8');
    } catch {
      continue;
    }

    for (const [ruleName, rule] of Object.entries(RULES)) {
      const violations = rule.check(content, relPath);
      for (const v of violations) {
        console.log(`[${ruleName}] ${v.file}:${v.line} ${v.detail || v.text}`);
        exitCode = 1;
      }
    }
  }

  if (exitCode === 0) {
    console.log('Conformance rules: all clean');
  }

  process.exit(exitCode);
}

main().catch(err => {
  console.error('conformance check error:', err);
  process.exit(2);
});

#!/usr/bin/env node
// Plank-join checker for Shipshape.
// Scans implementation directories for @planks(...) and @planks-provisional(...)
// annotations, reads step definitions from features/support, and reports the join.
// Exits non-zero when a behaviour-bearing seam has no plank, a plank matches no
// pattern, or a provisional plank names a scenario that lost its @captain tag.

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(fileURLToPath(import.meta.url), '..', '..');
const IMPLEMENTATION_DIRS = ['.', 'js', 'css'];
const SUPPORT_DIRS = ['features/support'];
const SPECS_DIR = 'features';

// --- Helpers ---

async function* walkFiles(dir, depth = 0) {
  if (depth > 6) return;
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
    if (entry.isDirectory()) {
      yield* walkFiles(fullPath, depth + 1);
    } else if (entry.isFile()) {
      yield fullPath;
    }
  }
}

// Extract @planks("...") and @planks-provisional("...") from file content.
// Also catches bare planks outside docblocks via token search.
function extractPlanks(content, filePath) {
  const planks = [];
  const provisional = [];

  // Match docblock annotations
  const docblockRe = /\/\*\*[\s\S]*?\*\//g;
  let match;
  while ((match = docblockRe.exec(content)) !== null) {
    const block = match[0];
    // @planks("pattern")
    let pm = block.match(/@planks\(\s*"([^"]+)"\s*\)/);
    if (pm) planks.push({ pattern: pm[1], location: `${filePath}:docblock` });
    // @planks-provisional("ref")
    let ppm = block.match(/@planks-provisional\(\s*"([^"]+)"\s*\)/);
    if (ppm) provisional.push({ scenario: ppm[1], location: `${filePath}:docblock` });
  }

  // Token search for planks outside docblocks (line comments, inline)
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Skip docblock lines
    if (line.trimStart().startsWith('*') || line.trimStart().startsWith('/**')) continue;
    // @planks("...")
    let pm = line.match(/@planks\(\s*"([^"]+)"\s*\)/);
    if (pm) {
      const isInDocblock = content.indexOf('/**') !== -1 && content.lastIndexOf('*/', content.indexOf(line)) > content.indexOf('/**', Math.max(0, content.indexOf(line) - 1000));
      if (!isInDocblock) planks.push({ pattern: pm[1], location: `${filePath}:${i + 1}:token` });
    }
    // @planks-provisional("...")
    let ppm = line.match(/@planks-provisional\(\s*"([^"]+)"\s*\)/);
    if (ppm) {
      const isInDocblock = content.indexOf('/**') !== -1 && content.lastIndexOf('*/', content.indexOf(line)) > content.indexOf('/**', Math.max(0, content.indexOf(line) - 1000));
      if (!isInDocblock) provisional.push({ scenario: ppm[1], location: `${filePath}:${i + 1}:token` });
    }
  }

  return { planks, provisional };
}

// Extract step definition patterns from support files.
function extractStepPatterns(content, filePath) {
  const patterns = [];

  // Cucumber-js step definitions: Given/When/Then(pattern, ...)
  const stepRe = /(?:Given|When|Then|And|But)\(\s*((['"`])((?:\\\2|(?!\2).)*?)\2)\s*,/g;
  let match;
  while ((match = stepRe.exec(content)) !== null) {
    patterns.push({ pattern: match[3], location: filePath, keyword: match[0].split('(')[0] });
  }

  // Also match regex patterns: /pattern/
  const regexRe = /(?:Given|When|Then|And|But)\(\s*\/((?:\\\/|[^\/])*)\/\s*,/g;
  while ((match = regexRe.exec(content)) !== null) {
    patterns.push({ pattern: match[1], location: filePath, keyword: match[0].split('(')[0], isRegex: true });
  }

  return patterns;
}

// Extract @captain scenario names from feature files.
async function extractCaptainScenarios() {
  const captainScenarios = new Set();
  const specsDir = path.join(ROOT, SPECS_DIR);

  for await (const filePath of walkFiles(specsDir)) {
    if (!filePath.endsWith('.feature')) continue;
    const content = await fs.readFile(filePath, 'utf8');
    const relPath = path.relative(ROOT, filePath);
    const lines = content.split('\n');

    // Tag-based approach: find scenarios tagged @captain
    let currentTags = [];
    let inScenario = false;
    let scenarioName = '';

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (line.startsWith('@')) {
        // Accumulate tags
        for (const tag of line.split(/\s+/)) {
          if (tag.startsWith('@')) currentTags.push(tag);
        }
        continue;
      }
      if (line.startsWith('Scenario Outline') || line.startsWith('Scenario:')) {
        scenarioName = line.replace(/^(Scenario Outline|Scenario):\s*/, '').trim();
        inScenario = true;
        if (currentTags.includes('@captain')) {
          captainScenarios.add(`${relPath}:${scenarioName}`);
        }
        currentTags = [];
        continue;
      }
      if (line.startsWith('Feature:') || line.startsWith('Background:') || line.startsWith('Rule:')) {
        currentTags = [];
        inScenario = false;
      }
      if (line === '' || line.startsWith('#')) continue;
    }
  }

  return captainScenarios;
}

// --- Main ---

async function main() {
  let exitCode = 0;
  const allPlanks = [];
  const allProvisional = [];
  const allPatterns = [];

  // 1. Scan implementation directories for planks
  for (const implDir of IMPLEMENTATION_DIRS) {
    const absDir = path.join(ROOT, implDir);
    try {
      await fs.access(absDir);
    } catch {
      continue; // directory doesn't exist yet (greenfield)
    }
    for await (const filePath of walkFiles(absDir)) {
      const ext = path.extname(filePath);
      if (!['.js', '.html', '.css', '.mjs', '.cjs', '.json'].includes(ext)) continue;
      const content = await fs.readFile(filePath, 'utf8');
      const relPath = path.relative(ROOT, filePath);
      const { planks, provisional } = extractPlanks(content, relPath);
      allPlanks.push(...planks);
      allProvisional.push(...provisional);
    }
  }

  // 2. Scan support directories for step definition patterns
  for (const supportDir of SUPPORT_DIRS) {
    const absDir = path.join(ROOT, supportDir);
    try {
      await fs.access(absDir);
    } catch {
      continue;
    }
    for await (const filePath of walkFiles(absDir)) {
      if (!filePath.endsWith('.js') && !filePath.endsWith('.mjs') && !filePath.endsWith('.cjs')) continue;
      const content = await fs.readFile(filePath, 'utf8');
      const relPath = path.relative(ROOT, filePath);
      const patterns = extractStepPatterns(content, relPath);
      allPatterns.push(...patterns);
    }
  }

  // 3. Read @captain scenarios from specs
  let captainScenarios;
  try {
    captainScenarios = await extractCaptainScenarios();
  } catch {
    captainScenarios = new Set();
  }

  // 4. Report the join
  console.log('PLANK JOIN REPORT');
  console.log('=================');

  // Report planks
  console.log('\n@planks annotations:');
  if (allPlanks.length === 0) {
    console.log('  (none)');
  } else {
    for (const plank of allPlanks) {
      const matched = allPatterns.some(p => p.pattern === plank.pattern);
      console.log(`  [${matched ? 'OK' : 'STALE'}] "${plank.pattern}" @ ${plank.location}`);
      if (!matched) exitCode = 1;
    }
  }

  // Report provisional planks
  console.log('\n@planks-provisional annotations:');
  if (allProvisional.length === 0) {
    console.log('  (none)');
  } else {
    for (const plank of allProvisional) {
      const stillCaptain = captainScenarios.has(plank.scenario);
      console.log(`  [${stillCaptain ? 'OK' : 'PROMOTED_OR_MISSING'}] "${plank.scenario}" @ ${plank.location}`);
      if (!stillCaptain) exitCode = 1;
    }
  }

  // Report patterns without planks
  console.log('\nStep patterns without matching planks:');
  const patternsWithoutPlanks = allPatterns.filter(p =>
    !allPlanks.some(pl => pl.pattern === p.pattern)
  );
  if (patternsWithoutPlanks.length === 0) {
    console.log('  (none)');
  } else {
    for (const p of patternsWithoutPlanks) {
      console.log(`  [UNPLANKED] "${p.pattern}" @ ${p.location}`);
      exitCode = 1;
    }
  }

  // Summary
  console.log(`\nSummary: ${allPlanks.length} @planks, ${allProvisional.length} @planks-provisional, ${allPatterns.length} step patterns`);

  process.exit(exitCode);
}

main().catch(err => {
  console.error('plank-join error:', err);
  process.exit(2);
});
